UPDATE entities SET summary = '本文首次刊登于2012年12月《Pen World》杂志 钢笔需要墨水。这个基本需求让每支钢笔都与墨水瓶——或其他墨水供应方式紧密相连。早在19世纪，制笔商就开始寻求更便捷的上墨方案，希望能摆脱滴管上墨的繁琐与脏乱。', updated_at = datetime('now') WHERE id = 'FMpW-glvNH9z' AND type = 'article';
