UPDATE entities SET summary = '早期的钢笔都由黑色硬橡胶（BHR）制成。每家制造商对设计都有独到见解，早期钢笔在外观上不可避免地存在差异——长度、直径、锥形末端等等——但对于纯黑材质来说，"增色添彩"的方式相对有限。当你见过一支细长的黑色硬橡胶钢笔后，基本上就等于看过了所有同类产品。', updated_at = datetime('now') WHERE id = 'XSay5an8Jrnp' AND type = 'article';
