UPDATE entities SET summary = '钢笔的消化系统由三个器官组成：储墨装置、笔尖，以及连接二者的笔舌（feed）。墨水通过笔舌从储墨装置流向笔尖。钢笔的墨水释放被称为"受控泄漏"，而实现这种控制的关键正是笔舌。', updated_at = datetime('now') WHERE id = 'YEvuxD1vFfkj' AND type = 'article';
