UPDATE entities SET summary = 'Frank告诉我（后来我也验证了这一点）：如果能在不损坏笔杆的情况下取出笔握，那么同样也能完好地装回去，且无需切削任何塑料。关键在于保持耐心——过快的推力、角度偏差或粗暴旋转都会导致笔杆开裂。要耐心。', updated_at = datetime('now') WHERE id = 'EJPGhbET0BkA' AND type = 'article';
