UPDATE entities SET summary = '无论是否属于第一梯队，所有钢笔制造商都自行生产全部笔尖的情况可能从未存在过。至少对于日本钢笔而言，有时可以识别特定钢笔中笔尖的制造商。日本标准协会制定并维护一套自1949年起实施的标准，适用于众多产品。', updated_at = datetime('now') WHERE id = '_VqzKPE0R2lv' AND type = 'article';
