UPDATE entities SET summary = '当今最流行的上墨系统其实早在两千年前就摆在发明家眼前。不过在您去考古现场掘地三尺之前... 从现代书写工具诞生之初到二十世纪早期，几乎所有钢笔都采用滴管上墨——尽管当今最流行的上墨系统其实早在两千年前就摆在发明家眼前。', updated_at = datetime('now') WHERE id = 'a59wmrBle3B2' AND type = 'article';
UPDATE entities SET summary = '本文源自对客户提问的回应，我决定保留问答形式，同时扩展内容以提供更全面的参考。部分术语具有技术性，其中大多数未在本文解释的术语已链接至我的《钢笔百科》或其他技术参考资料。', updated_at = datetime('now') WHERE id = 'SXUbDBjNeRom' AND type = 'article';
UPDATE entities SET summary = '若想从世界上最简单的上墨系统出发，最终演化出最复杂的上墨系统，这便是它的故事。 钢笔史上设计最简单的上墨机制是什么？如果你猜的是滴入式，那就错了。滴入式严格来说并非上墨机制，它更像是一个等待墨水注入的空容器——并非自动上墨，而是需要人工灌注。', updated_at = datetime('now') WHERE id = '02E52fbzVOAS' AND type = 'article';
