UPDATE entities SET summary = '首先应彻底清洁钢笔。拧下固定笔尖的小套环，拆卸笔的书写端部件。然后从后方将笔舌推出套环，笔尖会随之与笔舌分离。以下是笔握到笔尖的部件顺序示意图： 将这些部件与笔握浸泡在专用钢笔清洗液（或1:10的家用氨水溶液）中静置一夜。期间不时搅动。', updated_at = datetime('now') WHERE id = 'UoeCZhhEUrM9' AND type = 'article';
UPDATE entities SET summary = '这是2012年我在网络论坛发布的系列短文之一。鉴于互联网如同数字坟场，现将这些内容重新整理并永久保存于此。 众所周知，Walter A. Sheaffer 在1908年发明杠杆上墨装置，彻底革新了钢笔设计，对吧？', updated_at = datetime('now') WHERE id = 'Hy122-S2-nlo' AND type = 'article';
UPDATE entities SET summary = '在钢笔发明后的最初几十年里，钢笔由硬橡胶制成，笔帽通过滑动方式覆盖笔尖区域。硬橡胶滑动笔帽并不十分可靠——它们可能像滑上一样轻易滑落。如果笔帽在用户口袋中脱落，在发现松动的笔帽之前，墨水可能已染脏大部分衣物。19世纪90年代首次提出的解决方案是制造一种通过旋拧而非滑动固定的笔帽。', updated_at = datetime('now') WHERE id = 'Kugn6Qy1-Ket' AND type = 'article';
UPDATE entities SET summary = '若您更倾向于使用上墨器，Waterman在190年代为其优雅的Lady系列制作的上墨器与C/F完全匹配。截至本文撰写时，Waterman仍有少量库存。 首选方法是浸泡。使用清水或商用钢笔清洁液。若找不到清洁液，可用1份家用透明氨水兑10份水的溶液。', updated_at = datetime('now') WHERE id = 'eBu6dS2UI7tc' AND type = 'article';
UPDATE entities SET summary = '还剩多少墨水？ 当Lewis Waterman基本解决了提供可靠墨水流动的核心问题，并将洇墨现象控制在可接受范围后，19世纪钢笔用户最糟糕的遭遇莫过于在远离墨水补给时钢笔突然干涸。但如何预判危机？本文详述了制笔商为解决"墨水余量可视化"问题所设计的各种方案。', updated_at = datetime('now') WHERE id = 'dXg63Mp3vByz' AND type = 'article';
